// src/components/StudentForm.jsx
import React, { useState } from 'react';

export default function StudentForm({ mode='add', initial=null, onCancel, onSubmit }) {
  const [name, setName] = useState(initial ? initial.name : '');
  const [section, setSection] = useState(initial ? initial.section : '');
  const [marks, setMarks] = useState(initial ? initial.marks : '');
  const [grade, setGrade] = useState(initial ? initial.grade : '');

  const handleSubmit = (e) => {
    e.preventDefault();
    // basic validation
    if (!name.trim()) return alert('Please enter name');
    if (!section.trim()) return alert('Please enter section');
    if (marks === '' || Number.isNaN(Number(marks))) return alert('Please enter valid marks');
    if (!grade) return alert('Please select grade');

    const payload = { name: name.trim(), section: section.trim(), marks: Number(marks), grade: grade.trim() };
    if (mode === 'edit' && initial && initial.id) payload.id = initial.id;
    onSubmit(payload);
  };

  return (
    <div className="card">
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}}>
        <div style={{fontWeight:700}}>{mode === 'add' ? 'Add Student' : 'Edit Student'}</div>
        <div style={{color:'#9aa6bd',fontSize:13}}>{mode === 'add' ? 'Create new record' : 'Update existing record'}</div>
      </div>

      <form onSubmit={handleSubmit}>
        <div className="row">
          <div style={{flex:2}}>
            <label>Name</label>
            <input className="input" value={name} onChange={e => setName(e.target.value)} required />
          </div>

          <div style={{width:120}}>
            <label>Section</label>
            <input className="input small" value={section} onChange={e => setSection(e.target.value)} required />
          </div>
        </div>

        <div className="row">
          <div style={{flex:1}}>
            <label>Marks</label>
            <input type="number" className="input" value={marks} onChange={e => setMarks(e.target.value)} required />
          </div>

          <div style={{width:140}}>
            <label>Grade</label>
            <select className="input small" value={grade} onChange={e => setGrade(e.target.value)} required>
              <option value="">Select</option>
              <option value="A+">A+</option>
              <option value="A">A</option>
              <option value="B+">B+</option>
              <option value="B">B</option>
              <option value="C">C</option>
              <option value="D">D</option>
            </select>
          </div>
        </div>

        <div style={{display:'flex',gap:8,marginTop:8}}>
          <button className="btn primary" type="submit">{mode === 'add' ? 'Add Student' : 'Save Changes'}</button>
          <button className="btn" type="button" onClick={onCancel}>Cancel</button>
        </div>
      </form>
    </div>
  );
}
